import React, { useState, useMemo, useEffect } from 'react';
import { useTable, useFilters, useSortBy, usePagination } from 'react-table';
import './EventTable.css';

const EventTable = ({ events, loading, totalEvents, currentPage, pageSize, onPageChange }) => {
  const [columnFilters, setColumnFilters] = useState({});
  const [filteredData, setFilteredData] = useState([]);

  // Format date from YYYYMMDD to YYYY-MM-DD for display
  const formatDate = (dateStr) => {
    if (!dateStr || dateStr.length !== 8) return 'Unknown';
    return `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`;
  };

  // Get severity text based on serious flag
  const getSeverityText = (serious) => {
    return serious === 1 ? 'Serious' : 'Non-serious';
  };

  // Get patient gender text
  const getGenderText = (genderCode) => {
    switch (genderCode) {
      case 1: return 'Male';
      case 2: return 'Female';
      default: return 'Unknown';
    }
  };

  // 药物名标准化显示
  const getDrugName = (name) => {
    if (!name) return '';
    const n = name.toLowerCase();
    if (n === 'semaglutide') return 'Semaglutide';
    if (n === 'tirzepatide') return 'Tirzepatide';
    return name.charAt(0).toUpperCase() + name.slice(1).toLowerCase();
  };

  // 剂量单位代码映射
  const dosageUnitMap = {
    '001': 'mg',
    '002': 'g',
    '003': 'ml',
    '004': 'units',
    '005': 'ug',
    '006': 'ng',
    '007': 'meq',
    '008': 'mmol',
    '009': '%',
    '010': 'IU'
  };

  const getDosage = (num, unit) => {
    if (!num) return 'Unknown';
    if (unit && dosageUnitMap[unit]) return `${num} ${dosageUnitMap[unit]}`;
    if (unit) return `${num} ${unit}`;
    return num;
  };

  const formatRoute = (route) => {
    if (!route) return 'Unknown';
    return route.charAt(0).toUpperCase() + route.slice(1).toLowerCase();
  };

  // 为表格定义列
  const columns = useMemo(() => [
    {
      Header: 'Report ID',
      accessor: 'reportId',
      Cell: ({ row }) => row.original.top_safetyreportid
    },
    {
      Header: 'Report Date',
      accessor: 'reportDate',
      Cell: ({ row }) => formatDate(row.original.top_receivedate)
    },
    {
      Header: 'Event Country',
      accessor: 'eventCountry',
      Cell: ({ row }) => row.original.top_occurcountry || 'Unknown'
    },
    {
      Header: 'Medication',
      accessor: 'medication',
      Cell: ({ row }) => getDrugName(row.original.drug_medicinalproduct)
    },
    {
      Header: 'Adverse Event',
      accessor: 'adverseEvent',
      Cell: ({ row }) => row.original.reaction_reactionmeddrapt
    },
    {
      Header: 'Severity',
      accessor: 'severity',
      Cell: ({ row }) => getSeverityText(row.original.top_serious)
    },
    {
      Header: 'Gender',
      accessor: 'gender',
      Cell: ({ row }) => getGenderText(row.original.patient_patientsex)
    },
    {
      Header: 'Age',
      accessor: 'age',
      Cell: ({ row }) => row.original.patient_patientonsetage != null
        ? parseInt(row.original.patient_patientonsetage, 10)
        : 'Unknown'
    },
    {
      Header: 'Weight (kg)',
      accessor: 'weight',
      Cell: ({ row }) => row.original.patient_patientweight != null 
        ? row.original.patient_patientweight 
        : 'Unknown'
    },
    {
      Header: 'Route',
      accessor: 'route',
      Cell: ({ row }) => formatRoute(row.original.drug_openfda_route)
    },
    {
      Header: 'Start Date',
      accessor: 'startDate',
      Cell: ({ row }) => formatDate(row.original.drug_drugstartdate) || 'Unknown'
    },
    {
      Header: 'End Date',
      accessor: 'endDate',
      Cell: ({ row }) => formatDate(row.original.drug_drugenddate) || 'Unknown'
    },
    {
      Header: 'Dosage',
      accessor: 'dosage',
      Cell: ({ row }) => getDosage(
        row.original.drug_drugstructuredosagenumb,
        row.original.drug_drugstructuredosageunit
      )
    }
  ], []);

  // 处理列筛选
  const handleFilterChange = (columnId, value) => {
    setColumnFilters(prev => ({
      ...prev,
      [columnId]: value
    }));
  };

  // 计算每列的唯一值，用于筛选下拉菜单
  const getUniqueColumnValues = (data, columnId) => {
    if (!data || data.length === 0) return [];

    const uniqueValues = new Set();

    data.forEach(row => {
      const column = columns.find(col => col.accessor === columnId);
      if (column && column.Cell) {
        const cellValue = column.Cell({ row: { original: row } });
        if (cellValue !== undefined && cellValue !== null) {
          uniqueValues.add(String(cellValue));
        }
      }
    });

    return Array.from(uniqueValues).sort();
  };

  // 应用筛选逻辑
  useEffect(() => {
    if (!events || events.length === 0) {
      setFilteredData([]);
      return;
    }

    // 如果没有筛选条件，显示所有数据
    if (Object.keys(columnFilters).length === 0) {
      setFilteredData(events);
      return;
    }

    // 应用筛选
    const filtered = events.filter(row => {
      return Object.entries(columnFilters).every(([columnId, filterValue]) => {
        if (!filterValue) return true;

        const column = columns.find(col => col.accessor === columnId);
        if (!column) return true;

        const cellValue = column.Cell({ row: { original: row } });
        return String(cellValue).includes(filterValue);
      });
    });

    setFilteredData(filtered);
  }, [events, columnFilters, columns]);

  // 计算总页数
  const totalPages = Math.ceil(totalEvents / pageSize);

  // 生成分页号码
  const getPageNumbers = () => {
    const maxPagesToShow = 5;
    let startPage = Math.max(1, currentPage - Math.floor(maxPagesToShow / 2));
    let endPage = startPage + maxPagesToShow - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxPagesToShow + 1);
    }

    return Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);
  };

  // 清除所有筛选条件
  const clearAllFilters = () => {
    setColumnFilters({});
  };

  // 渲染筛选下拉菜单
  const renderFilterDropdown = (columnId) => {
    const uniqueValues = getUniqueColumnValues(events, columnId);

    return (
      <div className="column-filter-dropdown">
        <input 
          type="text" 
          placeholder="Filter..." 
          value={columnFilters[columnId] || ''} 
          onChange={(e) => handleFilterChange(columnId, e.target.value)}
          className="filter-input"
        />
        <div className="filter-values-list">
          {uniqueValues.map(value => (
            <div key={value} className="filter-value-item">
              <label>
                <input 
                  type="checkbox" 
                  checked={columnFilters[columnId] === value}
                  onChange={() => {
                    if (columnFilters[columnId] === value) {
                      handleFilterChange(columnId, '');
                    } else {
                      handleFilterChange(columnId, value);
                    }
                  }}
                />
                {value}
              </label>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const [activeFilterColumn, setActiveFilterColumn] = useState(null);

  const toggleFilterDropdown = (columnId) => {
    setActiveFilterColumn(prev => prev === columnId ? null : columnId);
  };

  return (
    <div className="event-table-container">
      {loading ? (
        <div className="loading-indicator">Loading data...</div>
      ) : filteredData.length === 0 ? (
        <div className="no-data-message">No adverse events found. Try adjusting your filters.</div>
      ) : (
        <>
          {Object.keys(columnFilters).length > 0 && (
            <div className="active-filters">
              <div className="active-filters-info">
                Active filters: {Object.entries(columnFilters).map(([col, val]) => (
                  val ? <span key={col} className="filter-badge">
                    {columns.find(c => c.accessor === col)?.Header}: {val}
                    <button onClick={() => handleFilterChange(col, '')}>×</button>
                  </span> : null
                ))}
              </div>
              <button className="clear-filters-btn" onClick={clearAllFilters}>
                Clear all filters
              </button>
            </div>
          )}

          <div className="table-responsive">
            <table className="event-table">
              <thead>
                <tr>
                  {columns.map(column => (
                    <th key={column.accessor} className="filterable-header">
                      <div className="header-content">
                        <span>{column.Header}</span>
                        <button 
                          className={`filter-button ${columnFilters[column.accessor] ? 'active' : ''}`}
                          onClick={() => toggleFilterDropdown(column.accessor)}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>
                          </svg>
                        </button>
                      </div>
                      {activeFilterColumn === column.accessor && (
                        renderFilterDropdown(column.accessor)
                      )}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filteredData.map((event) => (
                  <tr key={`${event.top_safetyreportid}-${event.reaction_reactionmeddrapt}`}>
                    <td>{event.top_safetyreportid}</td>
                    <td>{formatDate(event.top_receivedate)}</td>
                    <td>{event.top_occurcountry || 'Unknown'}</td>
                    <td>{getDrugName(event.drug_medicinalproduct)}</td>
                    <td>{event.reaction_reactionmeddrapt}</td>
                    <td>{getSeverityText(event.top_serious)}</td>
                    <td>{getGenderText(event.patient_patientsex)}</td>
                    <td>
                      {event.patient_patientonsetage != null
                        ? parseInt(event.patient_patientonsetage, 10)
                        : 'Unknown'}
                    </td>
                    <td>{event.patient_patientweight != null ? event.patient_patientweight : 'Unknown'}</td>
                    <td>{formatRoute(event.drug_openfda_route)}</td>
                    <td>{formatDate(event.drug_drugstartdate) || 'Unknown'}</td>
                    <td>{formatDate(event.drug_drugenddate) || 'Unknown'}</td>
                    <td>{getDosage(event.drug_drugstructuredosagenumb, event.drug_drugstructuredosageunit)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="pagination">
            <div className="pagination-info">
              Showing {(currentPage - 1) * pageSize + 1} to {Math.min(currentPage * pageSize, totalEvents)} of {totalEvents} records
            </div>

            <div className="pagination-controls">
              <button 
                className="pagination-button" 
                disabled={currentPage === 1}
                onClick={() => onPageChange(currentPage - 1)}
              >
                Previous
              </button>

              {getPageNumbers().map(number => (
                <button
                  key={number}
                  className={`pagination-button ${currentPage === number ? 'active' : ''}`}
                  onClick={() => onPageChange(number)}
                >
                  {number}
                </button>
              ))}

              <button 
                className="pagination-button" 
                disabled={currentPage === totalPages}
                onClick={() => onPageChange(currentPage + 1)}
              >
                Next
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default EventTable;
